function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 50) return 'grid needs 1 to 50 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 values.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows need the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v >= 2500)) return 'Each value is a whole number from 0 to 2499.';
  }
  return null;
}

