function minimumOperations(grid) {
  let operations = 0;
  for (let col = 0; col < grid[0].length; col++) {
    let previous = grid[0][col];
    for (let row = 1; row < grid.length; row++) {
      const target = Math.max(grid[row][col], previous + 1);
      operations += target - grid[row][col];
      previous = target;
    }
  }
  return operations;
}

