function minimumOperations(grid) {
  // Simulate the operations: keep adding 1 to the first cell that is not above the cell over it.
  const cells = grid.map(row => [...row]);
  let operations = 0;
  for (let col = 0; col < cells[0].length; col++) {
    for (;;) {
      let row = 1;
      while (row < cells.length && cells[row][col] > cells[row - 1][col]) row++;
      if (row === cells.length) break;
      cells[row][col]++;
      operations++;
    }
  }
  return operations;
}

