function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const m = size === 'large' ? int(40, 50) : int(1, 5);
  const n = size === 'large' ? int(40, 50) : int(1, 4);
  // Small value ranges create many equal neighbours; sometimes use the full range up to 2499.
  const top = rand() < 0.6 ? int(0, 9) : 2499;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, top)));
  // Sometimes sort every column, from high to low (the costliest order) or from low to high (nearly done).
  const order = int(0, 2);
  if (order > 0) {
    for (let c = 0; c < n; c++) {
      const column = grid.map(row => row[c]).sort((a, b) => order === 1 ? b - a : a - b);
      column.forEach((value, r) => { grid[r][c] = value; });
    }
  }
  return [grid];
}
